#include <iostream>
#include <windows.h>

HHOOK hHook;

LRESULT CALLBACK HookCallback(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (nCode == HC_ACTION && wParam == HSHELL_WINDOWCREATED)
    {
        HWND hWnd = reinterpret_cast<HWND>(lParam);
        int length = GetWindowTextLengthA(hWnd) + 1;
        if (length > MAX_PATH)
        {
            std::cout << "Process name too long." << std::endl;
            return CallNextHookEx(hHook, nCode, wParam, lParam);
        }

        char processName[MAX_PATH];
        ZeroMemory(processName, sizeof(processName));
        if (GetWindowTextA(hWnd, processName, length) == 0)
        {
            std::cout << "Failed to get window text." << std::endl;
            return CallNextHookEx(hHook, nCode, wParam, lParam);
        }

        // Validate process name (simple example)
        if (strpbrk(processName, "\\/:*?\"<>|") != nullptr)
        {
            std::cout << "Invalid process name." << std::endl;
            return CallNextHookEx(hHook, nCode, wParam, lParam);
        }

        std::cout << "Process created: " << processName << std::endl;
    }

    return CallNextHookEx(hHook, nCode, wParam, lParam);
}

int main()
{
    // Set the hook
    hHook = SetWindowsHookEx(WH_SHELL, HookCallback, NULL, 0);

    if (hHook == NULL)
    {
        std::cout << "Failed to set hook." << std::endl;
        return 1;
    }

    // Message loop
    MSG msg;
    while (GetMessage(&msg, NULL, 0, 0) > 0)
    {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Unhook the hook
    UnhookWindowsHookEx(hHook);

    return 0;
}
